function escapeHtml(value) {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderConceptCards(concepts) {
  if (!Array.isArray(concepts)) {
    throw new TypeError('concepts must be an array');
  }

  const cards = concepts.map(function (concept) {
    if (!concept || typeof concept !== 'object' || Array.isArray(concept) ||
        typeof concept.name !== 'string' || typeof concept.description !== 'string') {
      throw new TypeError('invalid concept');
    }
    return '<article><h2>' + escapeHtml(concept.name) + '</h2><p>' +
      concept.description + '</p></article>';
  }).join('');

  return '<section class="concepts"><h1>Concept Library</h1><div class="cards">' +
    cards + '</div></section>';
}

module.exports = { renderConceptCards };

