'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['renderConceptCards']);
const { renderConceptCards } = api;

assert.equal(
  renderConceptCards([]),
  '<section class="concepts"><h1>Concept Library</h1><div class="cards"></div></section>'
);

const concepts = [
  { name: 'A&B <Core>', description: 'Use "quotes" and \'apostrophes\'' },
  { name: '', description: '' }
];
const snapshot = JSON.stringify(concepts);
assert.equal(
  renderConceptCards(concepts),
  '<section class="concepts"><h1>Concept Library</h1><div class="cards"><article><h2>A&amp;B &lt;Core&gt;</h2><p>Use &quot;quotes&quot; and &#39;apostrophes&#39;</p></article><article><h2></h2><p></p></article></div></section>'
);
assert.equal(JSON.stringify(concepts), snapshot);
assert.equal(
  renderConceptCards([{ name: '&lt;', description: '&&' }]),
  '<section class="concepts"><h1>Concept Library</h1><div class="cards"><article><h2>&amp;lt;</h2><p>&amp;&amp;</p></article></div></section>'
);

for (const malformed of [null, {}, 'x', 1]) {
  assert.throws(() => renderConceptCards(malformed), TypeError);
}
assert.throws(() => renderConceptCards([null]), TypeError);
assert.throws(() => renderConceptCards([[]]), TypeError);
assert.throws(() => renderConceptCards([{}]), TypeError);
assert.throws(() => renderConceptCards([{ name: 1, description: 'x' }]), TypeError);
assert.throws(() => renderConceptCards([{ name: 'x', description: null }]), TypeError);

